//! The stage-5 real-machine switch gate (parity plan › stage 5, ADR 0105):
//! switch-keys.moho was generated by Moho Pro 14.4 (Lua: gen_switchbuild.lua) — a switch
//! layer "Mouths" holding two full copies of the gradients canvas ("Frown", and "Smile"
//! shifted by a layer offset), the selector keyed Frown at frame 0 and Smile at frame 12.
//! Moho's own FileRender frames are the truth: f0/f6 draw Frown in place, f12/f24 draw the
//! shifted Smile. This test renders the imported document through the CPU oracle and
//! compares content masks exactly like the stage-2 camera gate (translation-aligned F1 on
//! 4px cells).
//!
//! Negative control: the same document with the selector flipped (Smile picked at frame 0,
//! Frown at 12) must NOT match — the offset content arrives at the wrong frames, so the
//! aligned overlap collapses. Without this, a gate fed two similar frames could pass on the
//! stroke baseline alone.

use anicraft_mohoproj_import::import_path;
use std::path::{Path, PathBuf};
use std::sync::Arc;

fn corpus() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("MAOHOU_FIXTURES") {
        let p = PathBuf::from(dir);
        if p.is_dir() {
            return Some(p);
        }
    }
    let beside = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../maop-corpus/maop");
    beside.is_dir().then_some(beside)
}

/// Downsampled boolean content mask (alpha > 24), cell = `step` px, any-content vote.
fn content_mask(px: &[u8], w: u32, h: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let gw = w / step;
    let gh = h / step;
    let mut m = vec![false; (gw * gh) as usize];
    for gy in 0..gh {
        for gx in 0..gw {
            let mut on = 0u32;
            for dy in 0..step {
                for dx in 0..step {
                    let a = px[(((gy * step + dy) * w + gx * step + dx) * 4 + 3) as usize];
                    if a > 24 {
                        on += 1;
                    }
                }
            }
            m[(gy * gw + gx) as usize] = on > 0;
        }
    }
    (gw, gh, m)
}

/// Best translation (within ±`range` cells) aligning `a` onto `b`, by F1 overlap.
fn best_shift(a: &[bool], b: &[bool], gw: u32, gh: u32, range: u32) -> (i64, i64, f64) {
    let (mut best_dx, mut best_dy) = (0i64, 0i64);
    let mut best_f1 = -1f64;
    let count = |dx: i64, dy: i64| -> f64 {
        let mut inter = 0u64;
        let mut na = 0u64;
        let mut nb = 0u64;
        for y in 0..gh as i64 {
            for x in 0..gw as i64 {
                let vb = b[(y as u32 * gw + x as u32) as usize];
                let ax = x - dx;
                let ay = y - dy;
                let va = ax >= 0 && ax < gw as i64 && ay >= 0 && ay < gh as i64 && a[(ay as u32 * gw + ax as u32) as usize];
                if va {
                    na += 1;
                }
                if vb {
                    nb += 1;
                }
                if va && vb {
                    inter += 1;
                }
            }
        }
        if na + nb == 0 {
            return 0.0;
        }
        2.0 * inter as f64 / (na + nb) as f64
    };
    for dy in -(range as i64)..=(range as i64) {
        for dx in -(range as i64)..=(range as i64) {
            let f1 = count(dx, dy);
            if f1 > best_f1 {
                best_f1 = f1;
                best_dx = dx;
                best_dy = dy;
            }
        }
    }
    (best_dx, best_dy, best_f1)
}

fn straight_rgba(ours: &anicraft_render::Pixmap) -> Vec<u8> {
    let mut rgba = Vec::with_capacity((ours.width * ours.height * 4) as usize);
    for p in &ours.data {
        let a = p[3];
        let un = |c: f32| if a > 0.0 { (c / a).clamp(0.0, 1.0) } else { 0.0 };
        rgba.extend_from_slice(&[(un(p[0]) * 255.0) as u8, (un(p[1]) * 255.0) as u8, (un(p[2]) * 255.0) as u8, (a * 255.0) as u8]);
    }
    rgba
}

/// The imported document rendered at `frame`, as a content mask.
fn render_mask(doc: &anicraft_doc::Document, frame: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let (w, h) = (doc.stage.width, doc.stage.height);
    let dl = anicraft_doc::evaluate(doc, frame);
    let view = anicraft_render::View { transform: anicraft_geom::Affine::IDENTITY, width: w, height: h, background: None };
    let ours = anicraft_render::render(&dl, &view).unwrap().0;
    content_mask(&straight_rgba(&ours), w, h, step)
}

#[test]
fn imported_switch_matches_moho_frames() {
    let Some(dir) = corpus() else {
        eprintln!("skipped: no maop-corpus beside the workspace");
        return;
    };
    let path = dir.join("switch-keys.moho");
    if !path.is_file() {
        eprintln!("skipped: no switch-keys.moho in the corpus");
        return;
    }
    let (doc, report) = import_path(&path).unwrap_or_else(|e| panic!("switch-keys.moho: {e}"));
    // The switch arrived whole: a Switch layer with the two variants and the two keys.
    let mouths = doc.timeline(0).layers.iter().find(|l| l.kind == anicraft_doc::LayerKind::Switch).unwrap();
    let keys: Vec<(u32, &str)> = mouths.switch_to.keys.iter().map(|k| (k.frame, k.val.as_str())).collect();
    assert_eq!(keys, vec![(0, "Frown"), (12, "Smile")], "the selector keys straight from the file");
    let variants: Vec<&str> = doc.timeline(0).layers.iter().filter(|l| l.parent == Some(mouths.id)).map(|l| l.name.as_str()).collect();
    assert_eq!(variants.len(), 2, "both variants are children: {variants:?}");
    assert!(!report.skipped.contains_key("switch cross-fades (the switch steps between variants)"), "{:?}", report.skipped);

    // The wrong-variant control: flip every key's pick.
    let mut flipped = doc.clone();
    for l in flipped.timeline_mut(0).layers.iter_mut() {
        if l.kind == anicraft_doc::LayerKind::Switch {
            let l = Arc::make_mut(l);
            for k in &mut l.switch_to.keys {
                k.val = if k.val == "Frown" { "Smile".into() } else { "Frown".into() };
            }
        }
    }

    let (w, h) = (doc.stage.width, doc.stage.height);
    let step = 4u32;
    for (name, frame) in [("f0", 0u32), ("f6", 6), ("f12", 12), ("f24", 24)] {
        let Ok(moho_png) = std::fs::read(dir.join(format!("inputs/switch-keys-{name}.png"))) else {
            eprintln!("skipped {name}: no Moho render");
            continue;
        };
        let moho = anicraft_doc::decode_png(&moho_png).unwrap();
        assert_eq!((moho.width, moho.height), (w, h), "FileRender uses the document resolution");
        let (gw, gh, m_mask) = content_mask(&moho.rgba, w, h, step);
        let (gw2, gh2, o_mask) = render_mask(&doc, frame, step);
        assert_eq!((gw, gh), (gw2, gh2));
        let (dx, dy, f1) = best_shift(&o_mask, &m_mask, gw, gh, 75);
        println!("switch-keys {name}: best shift ({dx}, {dy}) cells = ({}px, {}px), aligned F1 {f1:.3}", dx * step as i64, dy * step as i64);
        let (fx, fy, wrong) = {
            let (_, _, w_mask) = render_mask(&flipped, frame, step);
            let (_, _, wf1) = best_shift(&w_mask, &m_mask, gw, gh, 75);
            (0, 0, wf1)
        };
        let _ = (fx, fy);
        println!("switch-keys {name}: WRONG-VARIANT control F1 {wrong:.3}");
        let why = format!("switch-keys {name}: aligned F1 {f1:.3} — the imported switch does not reproduce Moho's frame");
        assert!(f1 > 0.18, "{why}");
        let why = format!("switch-keys {name}: best shift ({dx}, {dy}) cells — the wrong content drew");
        assert!(dx.abs() <= 20 && dy.abs() <= 20, "{why}");
        let why = format!("switch-keys {name}: right variant F1 {f1:.3} must beat the flipped control {wrong:.3} — the selection is not what drives the pixels");
        assert!(f1 > wrong + 0.03, "{why}");
    }
}
